import fs from "node:fs";
import path from "node:path";

const root = "src";
const tagNames = ["app-fancy-pill", "app-status-pill"];
const tagRe = new RegExp(`<(${tagNames.join("|")})([^>]*?)(/?)>`, "gs");

function walk(dir, files = []) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full, files);
        else if (entry.name.endsWith(".ts") || entry.name.endsWith(".html")) files.push(full);
    }
    return files;
}

let totalEdits = 0;
let filesChanged = 0;

for (const file of walk(root)) {
    const original = fs.readFileSync(file, "utf8");
    let edits = 0;
    const updated = original.replace(tagRe, (match, tag, attrs, selfClose) => {
        let newAttrs = attrs;
        const before = newAttrs;
        newAttrs = newAttrs.replace(/\[disableTooltip\]/g, "[hideHint]");
        newAttrs = newAttrs.replace(/\bdisableTooltip\b/g, "hideHint");
        if (newAttrs !== before) edits++;
        return `<${tag}${newAttrs}${selfClose}>`;
    });
    if (updated !== original) {
        fs.writeFileSync(file, updated, "utf8");
        filesChanged++;
        totalEdits += edits;
        console.log(`${file}: ${edits} tag(s) updated`);
    }
}

console.log(`\nTotal: ${totalEdits} tag edits in ${filesChanged} files`);

