import fs from "node:fs";
import path from "node:path";

const root = "src";
const exclude = [
    /\bcard\(\)\??\.disableTooltip\(\)/g,
    /\bsummary\.disableTooltip\(\)/g,
];
const placeholder = "�KEEP�";

function walk(dir, files = []) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full, files);
        else if (entry.name.endsWith(".ts") || entry.name.endsWith(".html")) files.push(full);
    }
    return files;
}

let totalEdits = 0;
let filesChanged = 0;

for (const file of walk(root)) {
    const original = fs.readFileSync(file, "utf8");
    if (!original.includes(".disableTooltip()")) continue;
    const kept = [];
    let temp = original;
    for (const re of exclude) {
        temp = temp.replace(re, (m) => {
            kept.push(m);
            return placeholder + (kept.length - 1) + placeholder;
        });
    }
    const before = temp;
    temp = temp.replace(/\.disableTooltip\(\)/g, ".hideHint()");
    const edits = (before.match(/\.disableTooltip\(\)/g) || []).length;
    temp = temp.replace(new RegExp(placeholder + "(\\d+)" + placeholder, "g"), (_, i) => kept[Number(i)]);
    if (temp !== original) {
        fs.writeFileSync(file, temp, "utf8");
        filesChanged++;
        totalEdits += edits;
        console.log(`${file}: ${edits} edit(s)`);
    }
}

console.log(`\nTotal: ${totalEdits} edits in ${filesChanged} files`);

